tools.input:
B=<scratch>; R=$B/s1/R3; mkdir -p $R/work $R/state; cd $R/work
cat > q.tuft <<'E'
@h := find rx"decode_pin\(\s*&changed\(" in "crates/" at "c568505742d00859cad758924c98d8d0a6e98648" limit 100;
@e := retain @h around lines 0;
@v := project @e [path, line, excerpt(max_chars: 300)];
emit @v budget_tokens 4000;
E
$B/bin/writfold tuft run q.tuft --repo $R/repo --state $R/state
